<?phpnamespace hema\wechat;use app\common\model\Setting;use hema\Http;use think\facade\Cache;/** * 微信小程序接口 */class Wxapp{	private $config;    private $error;	/**	 * 构造函数	 */	public function __construct()	{	    $config = Setting::getItem('wxapp');		$this->config = $config;		if(empty($config['app_id']) or empty($config['app_secret'])){		    die(json_encode(['code' => 0, 'msg' => '服务端未配置微信小程序参数'],JSON_UNESCAPED_UNICODE));		}	}	    //订阅消息接口    // 接口参考文档：https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/mp-message-management/subscribe-message/getCategory.html    //####################################################################        /**    * 获取已设置的所有类目    */    public function getSettingCategories()    {        $access_token = $this->getAccessToken();        $url = 'https://api.weixin.qq.com/wxaapi/newtmpl/getcategory?access_token='.$access_token;        return $this->result(Http::get($url));    }    /**     * 获取帐号下的模板列表     */    public function getMessageTemplateList()    {        $access_token = $this->getAccessToken();        $url = 'https://api.weixin.qq.com/wxaapi/newtmpl/gettemplate?access_token='.$access_token;        return $this->result(Http::get($url));    }    /**     * 删除帐号下的模板     */    public function deleteMessageTemplate(string $tpl_id)    {        $access_token = $this->getAccessToken();        $url = 'https://api.weixin.qq.com/wxaapi/newtmpl/deltemplate?access_token='.$access_token;        $queryarr = [            'priTmplId' => $tpl_id        ];        return $this->result(Http::post($url, hema_json($queryarr),[],['content-type: application/json']));    }    /**     * 添加帐号下的模板     */    public function addMessageTemplate(string $tid, array $kidlist, string $desc)    {        $access_token = $this->getAccessToken();        $url = 'https://api.weixin.qq.com/wxaapi/newtmpl/addtemplate?access_token='.$access_token;        $queryarr = [            'tid' => $tid,            'kidList' => $kidlist,            'sceneDesc' => $desc        ];        return $this->result(Http::post($url, hema_json($queryarr),[],['content-type: application/json']));    }     /**     * 发送订阅消息     */    public function sendMessage(array $queryarr)    {        $access_token = $this->getAccessToken();        $url = 'https://api.weixin.qq.com/cgi-bin/message/subscribe/send?access_token='.$access_token;        $result = json_decode(Http::post($url,json_encode($queryarr)),true);        return true;     }    //####################################################################		/**     * 小程序登录    */    public function code2Session(string $code)    {        $url = 'https://api.weixin.qq.com/sns/jscode2session';        $params = [            'appid' => $this->config['app_id'],            'secret' => $this->config['app_secret'],            'grant_type' => 'authorization_code',            'js_code' => $code        ];        return $this->result(Http::get($url, $params));    }	/**     * 获取不限制数量的小程序码     * $path = 存放文件夹     */    public function getUnlimitedQRCode($file_name='',string $scene = '',$page = 'pages/index/index')    {        $access_token = $this->getAccessToken();        $url = 'https://api.weixin.qq.com/wxa/getwxacodeunlimit?access_token='.$access_token;        $queryarr = [            'scene' => $scene,            'page' => $page,            'check_path' => false,//不检测页面是否存在            //'is_hyaline' => true,//透明底色        ];        $result = Http::post($url,json_encode($queryarr));        //严正是否返回JSON数据        if(is_json($result)){            return $this->result($result);        }        file_put_contents('./'.$file_name,$result);         //获取的二维码数据存储到指定的文件        return $file_name;    }    /**     * 获取令牌 - AccessToken    */    private function getAccessToken()    {        $config = $this->config;        if(!$access_token = Cache::get('weixin_access_token','')){            //重新获取            $url = 'https://api.weixin.qq.com/cgi-bin/token';            $params = [                'grant_type' => 'client_credential',                'appid' => $config['app_id'],                'secret' => $config['app_secret']            ];            $result = json_decode(Http::get($url, $params),true);            if(isset($result['access_token'])){                $access_token = $result['access_token'];                Cache::set('weixin_access_token', $access_token, 7000); //设置将近2小时失效            }        }        return $access_token;    }    /**     * 请求数据验证     **/    private function result($result)    {        $result = json_decode($result,true);        if(!is_array($result)){            $this->error = '未知错误';			return false;        }        if(isset($result['errcode']) and $result['errcode']!=0){			$this->error = 'code：' . $result['errcode'] . '，msg：' . $result['errmsg'];			return false;		}		return $result;    }    public function getError()    {        return $this->error;    }   }